package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.view.View;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Separate name-list import. Exact matches selected; ambiguous results require a choice. */
final class NameBatchDialog {
 private final Context c;private final boolean media;private final Runnable saved;private final NativeSheet sheet;private final AccountRepository repo;private final EditText input;private final Spinner type;private final TextView state;private final LinearLayout results;private final Button search,add;private final List<JSONObject> chosen=new ArrayList<>();private List<String> names;private int index,kind,generation;private boolean searching;
 NameBatchDialog(Context c,boolean media,int initialType,Runnable saved){this.c=c;this.media=media;this.saved=saved;repo=new AccountRepository(c);sheet=new NativeSheet(c,media?"🍿 Adicionar lista de títulos":"🎮 Adicionar lista de jogos");type=NativeSheet.options(c,MediaInput.TYPES);type.setSelection(initialType);if(media)sheet.body.addView(type);sheet.body.addView(NativeSheet.text(c,"Cole até 50 nomes, um por linha. Também pode separar por ponto e vírgula.",13,0xffb8a8d7));input=NativeSheet.input(c,"Nome do primeiro título\nNome do segundo título",12000);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);input.setMinLines(5);input.setGravity(android.view.Gravity.TOP);sheet.body.addView(input);search=button("Buscar todos os nomes",true);sheet.body.addView(search);state=NativeSheet.text(c,"",13,0xffbbaaff);sheet.body.addView(state);results=new LinearLayout(c);results.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(results);sheet.footer.setVisibility(View.VISIBLE);add=button("Adicionar todos os selecionados",true);add.setEnabled(false);sheet.footer.addView(add);search.setOnClickListener(v->start());add.setOnClickListener(v->{JSONArray list=new JSONArray();for(JSONObject row:chosen)if(row!=null)list.put(row);if(list.length()==0)return;sheet.dialog.dismiss();new CatalogAddDialog(c,media,kind,list,saved,true);});sheet.dialog.setOnDismissListener(v->generation++);input.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int d){}public void afterTextChanged(android.text.Editable e){}public void onTextChanged(CharSequence s,int a,int b,int d){invalidate();}});type.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){invalidate();}});sheet.show();}
 private Button button(String label,boolean primary){Button b=new Button(c);b.setText(label);AppStyle.button(b,primary);return b;}
 private void invalidate(){if(searching)return;generation++;chosen.clear();results.removeAllViews();add.setEnabled(false);state.setText("");}
 private void start(){if(searching)return;try{names=BatchNames.parse(input.getText().toString());}catch(Exception e){state.setText(e.getMessage());return;}index=0;kind=type.getSelectedItemPosition();generation++;searching=true;chosen.clear();results.removeAllViews();search.setEnabled(false);input.setEnabled(false);type.setEnabled(false);add.setEnabled(false);next(generation);}
 private void next(int ticket){if(!sheet.dialog.isShowing()||ticket!=generation)return;if(index>=names.size()){searching=false;search.setEnabled(true);input.setEnabled(true);type.setEnabled(true);update();return;}String name=names.get(index);int slot=index++;chosen.add(null);state.setText("Buscando "+index+"/"+names.size()+" • "+name);AccountRepository.Callback cb=(rows,error)->{if(!sheet.dialog.isShowing()||ticket!=generation)return;result(name,slot,rows,error);next(ticket);};if(media)repo.searchMedia(name,kind,cb);else repo.searchGames(name,cb);}
 private void result(String name,int slot,JSONArray rows,String error){LinearLayout card=new LinearLayout(c);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(8),dp(12),dp(12));card.setBackground(AppStyle.shape(card,0xff211a31,16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(4));results.addView(card,lp);card.addView(NativeSheet.text(c,name,15,0xffeee6ff));List<JSONObject> matches=new ArrayList<>();List<String> labels=new ArrayList<>();labels.add("Não adicionar este título");int exact=0;if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null||row.optBoolean("adult"))continue;String title=row.optString(media?"nome":"name",row.optString("nome"));try{GameInput.name(title);}catch(Exception e){continue;}matches.add(row);labels.add(title);if(exact==0&&BatchNames.normalized(title).equals(BatchNames.normalized(name)))exact=matches.size();}
  if(error!=null||matches.isEmpty())card.addView(NativeSheet.text(c,error==null?"Não encontrado no catálogo.":error,12,0xffffba88));else if(exact==0)card.addView(NativeSheet.text(c,"Confira os resultados e selecione o título correto.",12,0xffffcb7f));
  // Manual entry is explicit, never silently substitutes a failed search.
  JSONObject manual=new JSONObject();try{manual.put("nome",name);}catch(JSONException ignored){}matches.add(manual);labels.add("Cadastrar pelo nome, sem dados do catálogo");Spinner select=NativeSheet.options(c,labels.toArray(new String[0]));card.addView(select);LinearLayout art=new LinearLayout(c);art.setOrientation(LinearLayout.VERTICAL);card.addView(art);select.setSelection(exact);if(exact>0)chosen.set(slot,matches.get(exact-1));int renderTicket=generation;select.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){if(renderTicket!=generation||slot>=chosen.size())return;JSONObject match=pos==0?null:matches.get(pos-1);chosen.set(slot,match);art.removeAllViews();if(match!=null)art.addView(CatalogCard.create(c,match.optString(media?"nome":"name",match.optString("nome")),match.optString(media?"capa":"background_image")));if(!searching)update();}});}
 private void update(){int count=0;for(JSONObject row:chosen)if(row!=null)count++;state.setText(count+" selecionado(s) • "+(names.size()-count)+" sem seleção");add.setEnabled(count>0);add.setText("Adicionar "+count+" título(s)");}
 private int dp(int n){return NativeSheet.dp(c,n);}
}
